<style>
  .followup-drawer{background:#fff;box-shadow:-18px 12px 42px rgba(15,23,42,.2);display:flex;flex-direction:column;height:min(720px,calc(100vh - 92px));max-width:calc(100vw - 20px);position:fixed;right:16px;top:76px;transform:translateX(calc(100% + 32px));transition:transform .22s ease;visibility:hidden;width:470px;z-index:1070}.followup-drawer.is-open{transform:translateX(0);visibility:visible}.followup-drawer__header{align-items:flex-start;background:linear-gradient(120deg,#123d67,#157fbf);color:#fff;display:flex;justify-content:space-between;padding:19px 20px}.followup-drawer__heading{display:flex;gap:11px}.followup-drawer__icon{align-items:center;background:rgba(255,255,255,.14);border:1px solid rgba(255,255,255,.22);border-radius:9px;display:inline-flex;font-size:19px;height:38px;justify-content:center;width:38px}.followup-drawer__heading p{color:rgba(255,255,255,.72);font-size:.68rem;font-weight:800;letter-spacing:.08em;margin:0;text-transform:uppercase}.followup-drawer__heading h2{color:#fff;font-size:1rem;font-weight:800;margin:3px 0 0}.followup-drawer__close{background:rgba(255,255,255,.12);border:1px solid rgba(255,255,255,.24);border-radius:7px;color:#fff;font-size:1rem;height:32px;width:32px}.followup-drawer__close:hover{background:rgba(255,255,255,.23)}.followup-drawer__meta{background:#f7fbff;border-bottom:1px solid #e4edf5;color:#506579;font-size:.82rem;padding:11px 20px}.followup-drawer__meta strong{color:#0c6097;font-size:1rem}.followup-drawer__tools{align-items:center;border-bottom:1px solid #e9eff5;display:flex;gap:12px;padding:13px 20px}.followup-drawer__tools label{align-items:center;border:1px solid #cbd8e5;border-radius:7px;display:flex;flex:1;padding:0 9px}.followup-drawer__tools label>i{color:#738296}.followup-drawer__tools input{border:0;font:inherit;min-width:0;outline:0;padding:8px;width:100%}.followup-drawer__tools button{background:transparent;border:0;color:#738296;padding:2px}.followup-drawer__tools p{color:#637083;font-size:.76rem;margin:0;white-space:nowrap}.followup-drawer__list{overflow:auto;padding:7px 12px 14px}.followup-drawer__row{align-items:center;border-bottom:1px solid #edf1f5;display:flex;gap:12px;justify-content:space-between;padding:13px 8px}.followup-drawer__row:hover{background:#f8fbfe}.followup-drawer__row-copy{min-width:0}.followup-drawer__row-copy strong,.followup-drawer__row-copy span,.followup-drawer__row-copy small{display:block}.followup-drawer__row-copy strong{color:#1c3145;font-size:.87rem;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.followup-drawer__row-copy span{color:#687a8d;font-size:.77rem;margin-top:3px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.followup-drawer__row-copy small{color:#8a98a7;font-size:.7rem;margin-top:3px}.followup-drawer__row-action{align-items:flex-end;display:flex;flex:0 0 auto;flex-direction:column;gap:7px}.followup-drawer__row-action time{background:#fff3e4;border-radius:99px;color:#a45108;font-size:.68rem;font-weight:800;padding:4px 7px}.followup-drawer__row-action a{color:#076da9;font-size:.75rem;font-weight:800;text-decoration:none}.followup-drawer__row-action a:hover{text-decoration:underline}.followup-drawer__empty{align-items:center;color:#6d7e8e;display:flex;flex-direction:column;padding:42px 18px;text-align:center}.followup-drawer__empty i{color:#268253;font-size:1.6rem;margin-bottom:10px}.followup-drawer__empty strong{color:#334b61;font-size:.9rem}.followup-drawer__empty span{font-size:.78rem;margin-top:4px}.followup-drawer__close:focus-visible,.followup-drawer__tools input:focus-visible,.followup-drawer__tools button:focus-visible{outline:3px solid #8dd4ff;outline-offset:2px}@media(max-width:575px){.followup-drawer{height:calc(100vh - 65px);right:0;top:65px;width:100%}}
</style>

<script>
document.addEventListener('DOMContentLoaded',function(){var drawer=document.getElementById('customerAlertDrawer'),open=document.getElementById('customerAlertToggle'),close=document.getElementById('customerAlertClose');if(!drawer||!open||!close)return;var input=document.getElementById('alertSearchInput'),clear=document.getElementById('alertSearchClear'),summary=document.getElementById('alertVisibleSummary'),rows=Array.prototype.slice.call(drawer.querySelectorAll('.followup-drawer__row')),empty=document.getElementById('alertNoResults');function setOpen(isOpen){drawer.classList.toggle('is-open',isOpen);drawer.setAttribute('aria-hidden',String(!isOpen));open.setAttribute('aria-expanded',String(isOpen));if(isOpen)window.setTimeout(function(){input.focus()},100)}function filterRows(){var query=input.value.trim().toLowerCase(),count=0;rows.forEach(function(row){var match=row.textContent.toLowerCase().indexOf(query)!==-1;row.hidden=!match;if(match)count++});empty.hidden=count!==0;summary.textContent=query?count+' match'+(count===1?'':'es'):count+' customer'+(count===1?'':'s');clear.hidden=!query}open.addEventListener('click',function(){setOpen(!drawer.classList.contains('is-open'))});close.addEventListener('click',function(){setOpen(false);open.focus()});input.addEventListener('input',filterRows);clear.addEventListener('click',function(){input.value='';filterRows();input.focus()});document.addEventListener('keydown',function(event){if(event.key==='Escape'&&drawer.classList.contains('is-open')){setOpen(false);open.focus()}})});
</script>
